mapper.select:
SELECT
    a.*
FROM account a
INNER JOIN customer c ON a.customer_id = c.id
WHERE a.account_no_hash = #{accountNoHash}
  AND c.rrn_prefix_enc = #{rrnPrefixEnc}

mapper.update:
UPDATE account
SET balance = balance - #{amount},
    version = version + 1,
    updated_at = NOW()
WHERE id = #{id}
  AND version = #{version}
  AND balance >= #{amount}
